BANK.push({
  s: "電子學", g: "高二上", ch: 3, id: "el-03", u: "雙極性接面電晶體",
  items: [
    {q: "雙極性接面電晶體（BJT）由幾個 PN 接面組成？", opts: ["3 個", "4 個", "1 個", "2 個"], ans: 3,
     sol: "BJT 由三層半導體構成兩個 PN 接面：射極—基極接面與集極—基極接面，故稱雙極性接面電晶體。"},
    {q: "BJT 的三個端子名稱為何？", opts: ["射極、基極、集極", "陽極、陰極、閘極", "輸入、輸出、接地", "源極、閘極、汲極"], ans: 0,
     sol: "BJT 為射極 E、基極 B、集極 C；源極 S／閘極 G／汲極 D 是場效電晶體（FET）的端子。"},
    {q: "BJT 中摻雜濃度最高、負責射出載子的是哪一極？", opts: ["三者相同", "射極", "基極", "集極"], ans: 1,
     sol: "射極摻雜最重以提供大量載子；基極最薄且摻雜最輕以減少復合；集極面積最大以利散熱。"},
    {q: "BJT 的基極做得很薄且摻雜濃度很低，目的為何？", opts: ["增加電容效應", "降低成本", "使多數載子能順利穿越到集極，減少在基極復合", "提高耐壓"], ans: 2,
     sol: "基極薄又輕摻雜，射極射出的載子大部分能穿越到集極，只有少部分形成基極電流，電流增益才會大。"},
    {q: "BJT 工作於主動區（放大區）時，兩個接面的偏壓狀態為何？", opts: ["射基接面逆偏、集基接面順偏", "兩個接面都順偏", "兩個接面都逆偏", "射基接面順偏、集基接面逆偏"], ans: 3,
     sol: "放大區：射基順偏、集基逆偏。兩個都順偏是飽和區（像開關 ON），兩個都逆偏是截止區（開關 OFF）。"},
    {q: "BJT 工作於飽和區時，兩個接面的偏壓狀態為何？", opts: ["都順偏", "都逆偏", "射基順偏、集基逆偏", "射基逆偏、集基順偏"], ans: 0,
     sol: "飽和區兩接面皆順偏，VCE 很小（矽約 0.2 V），相當於開關導通，數位電路以此作為低電位輸出。"},
    {q: "BJT 作為開關使用時，「截止」與「導通」分別對應哪兩個工作區？", opts: ["崩潰區與放大區", "截止區與飽和區", "放大區與截止區", "飽和區與放大區"], ans: 1,
     sol: "數位開關只用截止區（OFF）與飽和區（ON）；放大區才是類比放大用的。"},
    {q: "BJT 的三個電流關係為何？", opts: ["IC = IE + IB", "IE = IC − IB", "IE = IB + IC", "IB = IE + IC"], ans: 2,
     sol: "射極電流最大：IE = IB + IC，符合 KCL。"},
    {q: "共射極電流增益 β（hFE）的定義為何？", opts: ["IE/IC", "IB/IC", "IC/IE", "IC/IB"], ans: 3,
     sol: "β = IC/IB，一般在數十到數百之間，是放大能力的重要指標。"},
    {q: "共基極電流增益 α 的定義與數值範圍為何？", opts: ["α = IC/IE，略小於 1", "α = IC/IB，遠大於 1", "α = IE/IB，等於 β", "α = IB/IE，大於 1"], ans: 0,
     sol: "α = IC/IE，因為 IC 略小於 IE，α 約 0.95～0.995，永遠小於 1。"},
    {q: "α 與 β 的換算關係為何？", opts: ["β = 1/α", "β = α/(1 − α)", "β = (1 − α)/α", "β = α × (1 − α)"], ans: 1,
     sol: "β = α/(1 − α)，也可反推 α = β/(1 + β)。α = 0.99 時 β = 99。"},
    {q: "某 BJT 的 β = 100、IB = 20 μA，則 IC 為多少？", opts: ["2000 mA", "0.2 mA", "2 mA", "20 mA"], ans: 2,
     sol: "IC = β × IB = 100 × 20 μA = 2000 μA = 2 mA。"},
    {q: "承上題，IE 為多少？", opts: ["20 mA", "1.98 mA", "2 mA", "2.02 mA"], ans: 3,
     sol: "IE = IC + IB = 2 mA + 0.02 mA = 2.02 mA，略大於 IC。"},
    {q: "NPN 電晶體正常放大時，各端電位的大小順序為何？", opts: ["VC > VB > VE", "VE > VB > VC", "VB > VC > VE", "三者相等"], ans: 0,
     sol: "NPN 放大時集極電位最高、射極最低；PNP 則完全相反。"},
    {q: "矽質 NPN 電晶體放大時，VBE 約為多少？", opts: ["0.2 V", "0.7 V", "1.4 V", "5 V"], ans: 1,
     sol: "射基接面順偏，矽約 0.7 V、鍺約 0.3 V。飽和時 VBE 略升到 0.8 V、VCE 降到約 0.2 V。"},
    {q: "BJT 共射極輸出特性曲線的橫軸與縱軸分別為何？", opts: ["VCE 與 VBE", "VBE 與 IB", "VCE 與 IC", "IC 與 IB"], ans: 2,
     sol: "輸出特性以 VCE 為橫軸、IC 為縱軸，並以不同 IB 畫出一族曲線，可看出放大區近似水平。"},
    {q: "在輸出特性曲線上，放大區的曲線近似水平，代表什麼意義？", opts: ["IC 與 VCE 成正比", "IC 為零", "電晶體已燒毀", "IC 幾乎只由 IB 決定，與 VCE 無關"], ans: 3,
     sol: "這就是電晶體能當「電流控制電流源」的原因：IC 受 IB 控制，而不受 VCE 影響。"},
    {q: "直流負載線的兩個端點（截止點與飽和點）如何求得？", opts: ["IC = 0 時 VCE = VCC；VCE = 0 時 IC = VCC/RC", "兩點都在原點", "IC = β IB 與 IE = IC", "由 VBE 決定"], ans: 0,
     sol: "在輸出特性上畫一條連接 (VCC, 0) 與 (0, VCC/RC) 的直線，與某條 IB 曲線的交點即為工作點 Q。"},
    {q: "工作點（Q 點）設定不當會造成什麼問題？", opts: ["電源短路", "輸出波形失真", "電晶體變成電容", "頻率改變"], ans: 1,
     sol: "Q 點太靠近飽和區或截止區，輸出波形的一邊會被削掉，稱為飽和失真或截止失真。Q 點一般設在負載線中央。"},
    {q: "BJT 的 β 值受溫度影響的情形為何？", opts: ["與溫度成反比", "完全不受影響", "隨溫度升高而增大", "隨溫度升高而減小為零"], ans: 2,
     sol: "溫度升高 β 增大、ICBO 也增大，使 IC 上升、溫度再升高，形成熱跑脫。因此偏壓電路需要有穩定機制。"}
  ]
});

BANK.push({
  s: "電子學", g: "高二下", ch: 4, id: "el-04", u: "BJT 放大電路",
  items: [
    {q: "放大電路中「偏壓」的主要作用為何？", opts: ["降低電源電壓", "提高頻率", "提供交流訊號", "建立適當的直流工作點，使電晶體在放大區工作"], ans: 3,
     sol: "先用直流偏壓把 Q 點設在放大區中央，交流訊號才能完整地被放大而不失真。"},
    {q: "下列何種偏壓電路的工作點最穩定、實用上最常採用？", opts: ["分壓式偏壓（含射極電阻）", "基極直接接地", "固定偏壓", "集極回授偏壓"], ans: 0,
     sol: "分壓式偏壓以 R1、R2 分壓決定基極電位，再配合射極電阻產生負回授，Q 點幾乎不受 β 與溫度影響。"},
    {q: "分壓式偏壓中，射極電阻 RE 的主要功用為何？", opts: ["提高電壓增益", "提供直流負回授，穩定工作點", "降低輸入阻抗", "產生振盪"], ans: 1,
     sol: "IC 上升 → VE 上升 → VBE 下降 → IB 下降 → IC 回降，形成負回授而穩定 Q 點。"},
    {q: "射極旁路電容（CE）並聯在 RE 兩端的目的為何？", opts: ["降低頻率響應", "穩定直流工作點", "提高交流電壓增益", "阻隔直流"], ans: 2,
     sol: "交流時旁路電容把 RE 短路掉，使交流增益不被 RE 削弱；直流時電容開路，RE 仍發揮穩定作用。"},
    {q: "耦合電容（如輸入、輸出端的電容）的作用為何？", opts: ["提高電流", "穩定溫度", "通直流、阻交流", "阻直流、通交流"], ans: 3,
     sol: "耦合電容把前後級的直流工作點隔開，只讓交流訊號通過，避免互相影響偏壓。"},
    {q: "共射極放大電路的輸入與輸出相位關係為何？", opts: ["相差 180 度（反相）", "相差 45 度", "同相", "相差 90 度"], ans: 0,
     sol: "共射極是唯一會反相的組態：輸入上升使 IC 增大、VCE 下降，輸出因而反相。"},
    {q: "共集極放大電路（射極隨耦器）的特性為何？", opts: ["輸入阻抗極低", "電壓增益約為 1，電流增益大，輸入阻抗高、輸出阻抗低", "電壓增益極大、輸出反相", "電流增益小於 1"], ans: 1,
     sol: "射極隨耦器電壓增益接近 1 且同相，主要用作阻抗匹配與緩衝級。"},
    {q: "共基極放大電路的特性為何？", opts: ["電壓增益小於 1", "輸出反相", "電流增益約為 1，電壓增益大，輸入阻抗低", "電流增益極大、輸入阻抗高"], ans: 2,
     sol: "共基極 α ≒ 1，故電流增益約 1；輸入阻抗低、輸出阻抗高，高頻特性佳，常用於高頻放大。"},
    {q: "三種組態中，何者的輸入阻抗最高？", opts: ["共基極", "三者相同", "共射極", "共集極"], ans: 3,
     sol: "共集極（射極隨耦器）輸入阻抗最高、輸出阻抗最低，適合接在高阻抗訊號源之後當緩衝。"},
    {q: "三種組態中，何者同時具有電壓增益與電流增益，功率增益最大？", opts: ["共射極", "共集極", "共基極", "三者皆無"], ans: 0,
     sol: "共射極電壓與電流增益都大，功率增益最高，是最常用的放大組態。"},
    {q: "共射極放大電路的電壓增益約可用下列何者估算（含射極旁路）？", opts: ["Av ≒ re/RC", "Av ≒ −RC/re", "Av ≒ RC × re", "Av ≒ 1"], ans: 1,
     sol: "Av ≒ −RC/re（或 −RC/(re + RE')），負號代表反相。re 為射極內部動態電阻，約 26 mV/IE。"},
    {q: "若 IE = 1 mA，射極內部動態電阻 re 約為多少？", opts: ["2.6 kΩ", "2.6 Ω", "26 Ω", "260 Ω"], ans: 2,
     sol: "re ≒ 26 mV ÷ IE = 26 mV ÷ 1 mA = 26 Ω，這是小訊號分析的常用近似。"},
    {q: "VCC = 12 V、RC = 2 kΩ、IC = 3 mA 時，VCE 為多少？", opts: ["9 V", "12 V", "2 V", "6 V"], ans: 3,
     sol: "VCE = VCC − IC×RC = 12 − (3 mA × 2 kΩ) = 12 − 6 = 6 V。Q 點剛好在負載線中央，是理想的設定。"},
    {q: "小訊號放大電路分析時，直流電源 VCC 對交流訊號而言視為何者？", opts: ["接地（短路）", "電流源", "電阻", "開路"], ans: 0,
     sol: "理想電源沒有內阻且電壓固定，對交流而言是交流接地，畫交流等效電路時要把 VCC 接到地。"},
    {q: "放大電路發生「截止失真」時，輸出波形會如何？", opts: ["正半週被削平", "負半週被削平", "整體變小但不失真", "變成方波"], ans: 1,
     sol: "Q 點太靠近截止區時，電晶體在訊號負半週提前截止，輸出對應的半週被削掉。飽和失真則削另一邊。"},
    {q: "要讓放大電路能放大更大的訊號而不失真，Q 點應設在何處？", opts: ["靠近飽和點", "靠近截止點", "負載線的中央", "負載線之外"], ans: 2,
     sol: "Q 點設在負載線中央可得到最大的不失真輸出擺幅。"},
    {q: "射極隨耦器最常見的用途為何？", opts: ["整流", "振盪", "電壓放大", "阻抗匹配與緩衝"], ans: 3,
     sol: "高輸入阻抗避免對前級造成負載效應，低輸出阻抗可驅動較重的負載，是典型的緩衝級。"},
    {q: "放大電路的電壓增益若為 −50，代表什麼？", opts: ["放大 50 倍且反相", "衰減為 1/50", "放大 50 倍且同相", "輸出為負電壓"], ans: 0,
     sol: "數值表示放大倍率，負號只代表相位反轉 180 度，不是輸出變成負電壓。"},
    {q: "分壓式偏壓電路中，若把射極電阻 RE 取消，會有什麼後果？", opts: ["工作點更穩定", "工作點容易受 β 與溫度影響而漂移", "電流變為零", "輸入阻抗變高"], ans: 1,
     sol: "沒有 RE 就沒有直流負回授，Q 點會隨溫度與元件差異漂移，嚴重時導致熱跑脫。"},
    {q: "電壓增益 40 dB 相當於多少倍？", opts: ["4 倍", "40 倍", "100 倍", "400 倍"], ans: 2,
     sol: "dB = 20log(Av)，40 = 20log(Av) → log(Av) = 2 → Av = 100 倍。20 dB 是 10 倍、60 dB 是 1000 倍。"}
  ]
});

